/* ZenNotes × Herdr isolated UX proof: NO live agent dispatch or cloud sync. */
(function(){
'use strict';
var KEY='zen-herdr-spike-v1';
var sample=[
{id:'n-idea',title:'Mobile agent workspace',body:'A notes app should feel immediate on iPhone.\n\nSelect any sentence to highlight it, create a task, or start an agent thread attached to the exact text.\n\nThe agent can investigate questions and report back without silently overwriting the source note.\n\nNext: verify the Herdr bridge identity, secure dispatch permissions, and live session events.',updated:Date.now()},
{id:'n-questions',title:'Questions to resolve',body:'What should happen when a selected sentence changes?\n\nShould an agent reply as a comment, a proposed edit, or a task?\n\nHow will live results sync across the phone and Mac?\n\nWhat approval is required before an agent modifies a note?',updated:Date.now()-1000},
{id:'n-project',title:'Project sketch',body:'Goal: build a compact, fast, mobile-first place for notes, threads, tasks, and agent work.\n\nHerdr should remain the session layer underneath the notes experience, not turn the editor into a terminal.',updated:Date.now()-2000}
];
function safeLoad(){try{var v=JSON.parse(localStorage.getItem(KEY));if(v&&Array.isArray(v.notes)&&Array.isArray(v.threads)&&Array.isArray(v.highlights)&&Array.isArray(v.tasks)){return v;}}catch(e){}return {notes:sample,threads:[],highlights:[],tasks:[]};}
var data=safeLoad(),route='notes',openNote='n-idea',selection=null,activeThread=null,editing=false,dirty=false;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(data));return true;}catch(e){alert('Browser storage is unavailable. Changes may be lost.');return false;}}
function E(s){return String(s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function newId(){return (crypto&&crypto.randomUUID)?crypto.randomUUID():'id-'+Date.now()+'-'+Math.floor(Math.random()*100000);}
function hash(s){var h=2166136261;for(var i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return (h>>>0).toString(16);}
function note(){return data.notes.find(function(n){return n.id===openNote;})||data.notes[0];}
function stamp(d){return new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric'});}
function getAnchor(a,n){if(n.body.slice(a.start,a.end)===a.quote&&hash(a.quote)===a.hash)return {start:a.start,end:a.end};
var first=n.body.indexOf(a.quote);if(first>=0&&n.body.indexOf(a.quote,first+1)<0)return {start:first,end:first+a.quote.length};
return null;}
function highlightsFor(n){return data.highlights.filter(function(h){return h.noteId===n.id;}).map(function(h){return {h:h,a:getAnchor(h,n)};}).filter(function(p){return !!p.a;}).sort(function(x,y){return x.a.start-y.a.start;});}
function markedText(n){var s=n.body,pos=0,out='',ranges=highlightsFor(n);ranges.forEach(function(p){if(p.a.start<pos)return;out+=E(s.slice(pos,p.a.start));out+='<mark class="'+(p.h.threadId?'thread-mark':'')+'" data-highlight="'+E(p.h.id)+'">'+E(s.slice(p.a.start,p.a.end))+'</mark>';pos=p.a.end;});return out+E(s.slice(pos));}
function nav(){return '<nav class="bottom-nav" aria-label="Primary navigation">'+[['notes','▤','Notes'],['tasks','☑','Tasks'],['threads','▢','Threads'],['agents','⌘','Agents']].map(function(p){return '<button class="nav '+(route===p[0]?'active':'')+'" data-route="'+p[0]+'"><span class="sym">'+p[1]+'</span><span class="lbl">'+p[2]+'</span></button>';}).join('')+'</nav>';}
function header(){var n=note();return '<header><div class="header-left">'+(route==='detail'?'<button class="icon-btn" data-route="notes" aria-label="Back to notes">‹</button>':'')+'<span class="header-title">'+E(route==='detail'?n.title:route==='notes'?'Notes':route==='tasks'?'Tasks':route==='threads'?'Threads':'Agents')+'</span></div><div class="header-right">'+(route==='detail'?'<button class="mini-action" data-action="edit">'+(editing?'Done':'Edit')+'</button>':'<span class="tag">Preview</span>')+'</div></header>';}
function notesView(){return '<main><div class="space-between"><h1 class="view-title">Your notes</h1><button class="mini-action" data-action="new">+ New</button></div><div class="note-list">'+data.notes.map(function(n){return '<button class="note-item" data-note="'+E(n.id)+'"><div class="space-between"><span class="name">'+E(n.title)+'</span><span class="subtle">'+stamp(n.updated)+'</span></div><div class="excerpt">'+E(n.body.replace(/\s+/g,' ').slice(0,110))+'</div></button>';}).join('')+'</div><p class="notice">Isolated staging proof · Notes stay in this browser, not ZenNotes Cloud.</p></main>';}
function detailView(){var n=note(),hs=highlightsFor(n);return '<main><div class="kicker"><span>NOTE · '+stamp(n.updated)+'</span><span>'+hs.length+' highlights · '+data.threads.filter(function(t){return t.noteId===n.id;}).length+' threads</span></div><h1 class="note-heading">'+E(n.title)+'</h1>'+(editing?'<textarea id="note-edit" class="note-edit" aria-label="Edit note">'+E(n.body)+'</textarea><div class="notice">Tap Done to save. Changed text may require re-anchoring existing threads.</div>':'<div class="note-text" id="note-text">'+markedText(n)+'</div>')+'<div class="action-row"><button data-action="edit">'+(editing?'Finish editing':'Edit note')+'</button><button data-action="threads-on-note">Threads ('+data.threads.filter(function(t){return t.noteId===n.id;}).length+')</button></div><p class="notice">Select text to open actions. No agent command is sent by this prototype.</p></main>';}
function tasksView(){return '<main><h1 class="view-title">Tasks</h1><div class="eyebrow">From selected text</div>'+(data.tasks.length?data.tasks.map(function(t){return '<label class="task-row"><input type="checkbox" data-task="'+E(t.id)+'" '+(t.done?'checked':'')+'><span style="'+(t.done?'text-decoration:line-through;color:#888':'')+'">'+E(t.text)+'</span></label>';}).join(''):'<div class="empty">Select text inside a note, then choose Create task.</div>')+'<p class="notice">Local staging tasks only · Not dispatched to an agent.</p></main>';}
function threadsView(){var a=data.threads.filter(function(t){return !window.__noteFilter||t.noteId===window.__noteFilter;});return '<main><h1 class="view-title">Threads</h1><div class="eyebrow">'+(window.__noteFilter?'For current note':'Anchored to selected text')+'</div>'+(a.length?a.map(function(t){return '<button class="thread-card" data-thread="'+E(t.id)+'"><div class="space-between"><strong>@'+E(t.agent)+' · '+E(t.status)+'</strong><span class="subtle">'+stamp(t.created)+'</span></div><p>“'+E(t.quote.slice(0,145))+'”</p></button>';}).join(''):'<div class="empty">No threads yet. Select a passage in a note to start one.</div>')+(window.__noteFilter?'<button class="btn" data-action="all-threads">Show all threads</button>':'')+'</main>';}
function agentsView(){return '<main><h1 class="view-title">Agents</h1><div class="eyebrow">Connection status</div><div class="disconnected"><span class="dot"></span><div><strong>Herdr disconnected</strong><div class="subtle" style="margin-top:5px;line-height:1.5">The bridge host, authentication, and session protocol have not been verified. This preview will not issue terminal commands or claim agent activity.</div></div></div><div class="agent-block"><div class="space-between"><strong>@pi</strong><span class="pill">Not connected</span></div><p class="subtle">Available as a draft thread target, not an executable runtime.</p></div><div class="agent-block"><div class="space-between"><strong>@codex</strong><span class="pill">Not connected</span></div><p class="subtle">No live session has been discovered or created.</p></div><div class="eyebrow">Next gate</div><p class="subtle" style="line-height:1.7">Verify a running Herdr host through the governed control plane, establish authenticated HTTPS transport, then add task dispatch, event subscription, read-back, and agent write approvals.</p></main>';}
function render(){document.getElementById('app').innerHTML=header()+(route==='notes'?notesView():route==='detail'?detailView():route==='tasks'?tasksView():route==='threads'?threadsView():agentsView())+nav();if(activeThread)drawSheet();if(selection&&route==='detail'&&!editing)drawSelectionBar();}
function resetSelection(){selection=null;var bar=document.getElementById('selection-actions');if(bar)bar.remove();}
function drawSelectionBar(){var old=document.getElementById('selection-actions');if(old)old.remove();if(!selection)return;var el=document.createElement('div');el.className='selection-actions';el.id='selection-actions';el.innerHTML='<button data-action="highlight">Highlight</button><button data-action="thread">Start thread</button><button data-action="task">Create task</button>';document.body.appendChild(el);}
function measureSelection(){if(route!=='detail'||editing||activeThread)return;var root=document.getElementById('note-text'),sel=window.getSelection();if(!root||!sel||sel.isCollapsed||!sel.rangeCount)return;var r=sel.getRangeAt(0);if(!root.contains(r.startContainer)||!root.contains(r.endContainer))return;var before=document.createRange();before.selectNodeContents(root);before.setEnd(r.startContainer,r.startOffset);var start=before.toString().length,quote=r.toString();if(!quote.trim())return;selection={noteId:note().id,start:start,end:start+quote.length,quote:quote,hash:hash(quote)};drawSelectionBar();}
function saveHighlight(threadId){if(!selection||selection.noteId!==note().id)return;var matched=data.highlights.find(function(h){return h.noteId===selection.noteId&&h.start===selection.start&&h.end===selection.end&&h.quote===selection.quote;});if(matched){if(threadId)matched.threadId=threadId;}else data.highlights.push(Object.assign({id:newId(),created:Date.now(),threadId:threadId||null},selection));persist();}
function createThread(){if(!selection)return;var s=selection;var t={id:newId(),noteId:s.noteId,quote:s.quote,start:s.start,end:s.end,hash:s.hash,agent:'pi',status:'draft',created:Date.now(),messages:[]};data.threads.push(t);saveHighlight(t.id);activeThread=t.id;resetSelection();window.getSelection()?.removeAllRanges();render();}
function createTask(){if(!selection)return;data.tasks.unshift({id:newId(),noteId:selection.noteId,text:selection.quote.trim(),done:false,created:Date.now()});persist();resetSelection();window.getSelection()?.removeAllRanges();render();}
function startHighlight(){if(!selection)return;saveHighlight(null);resetSelection();window.getSelection()?.removeAllRanges();render();}
function drawSheet(){var t=data.threads.find(function(x){return x.id===activeThread;});if(!t){activeThread=null;return;}var old=document.getElementById('sheet-backdrop');if(old)old.remove();var host=document.createElement('div');host.className='sheet-backdrop';host.id='sheet-backdrop';host.innerHTML='<div class="sheet" role="dialog" aria-modal="true" aria-label="Agent thread"><div class="handle"></div><div class="space-between"><h2>Agent thread</h2><button class="icon-btn" data-action="close-sheet" aria-label="Close">×</button></div><div class="space-between"><span class="tag">@'+E(t.agent)+' · '+E(t.status)+'</span><span class="subtle">Local draft · not sent</span></div><div class="quote">“'+E(t.quote)+'”</div>'+t.messages.map(function(m){return '<div class="message"><strong>You</strong> · '+E(m.text)+'</div>';}).join('')+'<textarea id="thread-compose" class="reply" placeholder="@pi Investigate this passage…" aria-label="Thread message"></textarea><div class="sheet-actions"><button class="btn primary" data-action="save-reply">Save draft message</button><button class="btn" disabled title="Herdr is not authenticated">Dispatch unavailable</button></div><p class="notice">Saving a message does not run an agent. Herdr integration is blocked on authenticated host + event verification.</p></div>';document.body.appendChild(host);}
function sendDraft(){var input=document.getElementById('thread-compose');var t=data.threads.find(function(x){return x.id===activeThread;});if(!input||!t||!input.value.trim())return;var value=input.value.trim();var match=value.match(/^@(pi|codex)\b/i);if(match)t.agent=match[1].toLowerCase();t.messages.push({id:newId(),text:value,at:Date.now(),source:'user'});persist();drawSheet();}
function editToggle(){var n=note();if(!editing){editing=true;resetSelection();render();document.getElementById('note-edit').focus();}else{var el=document.getElementById('note-edit');if(el&&el.value!==n.body){n.body=el.value;n.updated=Date.now();persist();}editing=false;render();}}
function createNote(){var n={id:newId(),title:'Untitled note',body:'Tap Edit to start writing.',updated:Date.now()};data.notes.unshift(n);openNote=n.id;route='detail';editing=true;persist();render();}
document.addEventListener('click',function(evt){var el=evt.target.closest('[data-action],[data-route],[data-note],[data-thread]');if(!el)return;if(el.dataset.route){route=el.dataset.route;window.__noteFilter=null;activeThread=null;editing=false;resetSelection();render();return;}
if(el.dataset.note){openNote=el.dataset.note;route='detail';editing=false;resetSelection();render();return;}if(el.dataset.thread){activeThread=el.dataset.thread;render();return;}
var a=el.dataset.action;if(!a)return;
if(a==='highlight')startHighlight();
if(a==='thread')createThread();
if(a==='task')createTask();
if(a==='edit')editToggle();
if(a==='new')createNote();
if(a==='threads-on-note'){window.__noteFilter=openNote;route='threads';resetSelection();render();}
if(a==='all-threads'){window.__noteFilter=null;render();}
if(a==='close-sheet'){activeThread=null;render();}
if(a==='save-reply')sendDraft();
});
document.addEventListener('change',function(evt){var t=evt.target;if(t.dataset&&t.dataset.task){var task=data.tasks.find(function(x){return x.id===t.dataset.task;});if(task){task.done=t.checked;persist();render();}}});
document.addEventListener('selectionchange',function(){if(route==='detail'&&!editing){setTimeout(measureSelection,170);}});
document.addEventListener('touchend',function(){if(route==='detail'&&!editing)setTimeout(measureSelection,250);});
document.addEventListener('mouseup',function(){if(route==='detail'&&!editing)setTimeout(measureSelection,60);});
document.addEventListener('click',function(evt){if(evt.target.id==='sheet-backdrop'){activeThread=null;render();}});
render();
})();